async def act(page):
    """
    From the current Dashboard, navigate to the Manage Products page and add a simple product
    named "Energy-Bulk Man Yoga Pant" with price 69.99, qty 50, size 38 and color Yellow.

    Notes:
    - Uses a relative goto to /index.php/admin/catalog_product/ (keeps navigation deterministic).
    - The final action is the Save click (it may navigate away), so no selectors follow it.
    - Uses combobox.select_option(...) for <select> elements per the accessibility tree guidance.
    """
    # Navigate to Manage Products (relative path from current admin origin)
    await page.goto("/index.php/admin/catalog_product/")
    await page.wait_for_load_state("networkidle")

    # Click Add Product (try button or link alternatives)
    add_clicked = False
    try:
        btn = page.get_by_role("button", name="Add Product")
        if await btn.count() > 0:
            await btn.click()
            add_clicked = True
    except Exception:
        pass
    if not add_clicked:
        try:
            # sometimes labeled "Add New Product"
            btn2 = page.get_by_role("button", name="Add New Product")
            if await btn2.count() > 0:
                await btn2.click()
                add_clicked = True
        except Exception:
            pass
    if not add_clicked:
        try:
            # fallback to a link
            link = page.get_by_role("link", name="Add Product")
            if await link.count() > 0:
                await link.click()
                add_clicked = True
        except Exception:
            pass

    # Wait a moment for any attribute-set/product-type dialog or the product form to appear
    await page.wait_for_load_state("networkidle")

    # If an attribute set combobox is present, try to choose 'Default'
    try:
        attr_set = page.get_by_role("combobox", name=lambda n: n and "attribute set" in n.lower())
        if await attr_set.count() > 0:
            # select by visible option label
            await attr_set.select_option("Default")
    except Exception:
        # try alternative name
        try:
            attr_set2 = page.get_by_role("combobox", name="Attribute Set")
            if await attr_set2.count() > 0:
                await attr_set2.select_option("Default")
        except Exception:
            pass

    # If product type radio appears, choose Simple
    try:
        simple_radio = page.get_by_role("radio", name=lambda n: n and "simple" in n.lower())
        if await simple_radio.count() > 0:
            await simple_radio.check()
    except Exception:
        pass

    # Click Continue if present to reach the product edit form
    try:
        cont = page.get_by_role("button", name=lambda n: n and ("continue" in n.lower() or n.lower()=="ok"))
        if await cont.count() > 0:
            await cont.click()
            await page.wait_for_load_state("networkidle")
    except Exception:
        pass

    # Fill in product fields
    # Name
    try:
        name_box = page.get_by_role("textbox", name=lambda n: n and "name" in n.lower())
        if await name_box.count() > 0:
            await name_box.fill("Energy-Bulk Man Yoga Pant")
    except Exception:
        pass

    # Price
    try:
        price_box = page.get_by_role("textbox", name=lambda n: n and "price" in n.lower())
        if await price_box.count() > 0:
            await price_box.fill("69.99")
    except Exception:
        pass

    # Status -> Enabled
    try:
        status = page.get_by_role("combobox", name=lambda n: n and "status" in n.lower())
        if await status.count() > 0:
            await status.select_option("Enabled")
    except Exception:
        pass

    # Visibility -> Catalog, Search
    try:
        vis = page.get_by_role("combobox", name=lambda n: n and "visibility" in n.lower())
        if await vis.count() > 0:
            await vis.select_option("Catalog, Search")
    except Exception:
        pass

    # Inventory: open Inventory tab (if present) and set Qty and Stock Availability
    try:
        inv_tab = page.get_by_role("tab", name=lambda n: n and "inventory" in n.lower())
        if await inv_tab.count() > 0:
            await inv_tab.click()
            # small pause for inventory pane to render
            await page.wait_for_timeout(500)
    except Exception:
        pass

    try:
        qty_box = page.get_by_role("textbox", name=lambda n: n and ("qty" in n.lower() or "quantity" in n.lower()))
        if await qty_box.count() > 0:
            await qty_box.fill("50")
    except Exception:
        pass

    try:
        stock = page.get_by_role("combobox", name=lambda n: n and ("stock" in n.lower() or "availability" in n.lower()))
        if await stock.count() > 0:
            await stock.select_option("In Stock")
    except Exception:
        pass

    # Attributes: Size and Color
    try:
        size = page.get_by_role("combobox", name=lambda n: n and "size" in n.lower())
        if await size.count() > 0:
            await size.select_option("38")
    except Exception:
        pass

    try:
        color = page.get_by_role("combobox", name=lambda n: n and "color" in n.lower())
        if await color.count() > 0:
            # try label variants
            for label in ["Yellow", "yellow"]:
                try:
                    await color.select_option(label)
                    break
                except Exception:
                    continue
    except Exception:
        pass

    # As a final safety, ensure any other Qty fields are set to 50 (redundant attempt)
    try:
        other_qty = page.get_by_role("textbox", name=lambda n: n and "qty" in n.lower())
        if await other_qty.count() > 0:
            await other_qty.fill("50")
    except Exception:
        pass

    # Final action: Save (this will likely navigate away; do not attempt any selectors after this)
    # Prefer scoping Save inside a form if possible
    try:
        form = page.get_by_role("form")
        if await form.count() > 0:
            save_btn = form.get_by_role("button", name=lambda n: n and "save" in n.lower())
            if await save_btn.count() > 0:
                await save_btn.click()
                return
    except Exception:
        pass

    # Fallback: any Save button on the page
    try:
        save_any = page.get_by_role("button", name=lambda n: n and "save" in n.lower())
        if await save_any.count() > 0:
            await save_any.click()
            return
    except Exception:
        pass

    # Last resort: link named Save
    try:
        save_link = page.get_by_role("link", name=lambda n: n and "save" in n.lower())
        if await save_link.count() > 0:
            await save_link.click()
            return
    except Exception:
        pass

    raise RuntimeError("Could not find a Save control to complete product creation")

